  text-align: left;
}
.feature-card svg { margin-bottom: 1rem; }
.feature-card h3 { margin-top: 0; }

/* --------------------------------------------------
   PRICING
--------------------------------------------------- */
.pricing {
  padding: 60px 0;
  background: #f9fafb;
}
.pricing h2 { text-align: center; margin-bottom: 40px; }
.price-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 30px;
}
.plan-card {
  background: #fff;
  border-radius: 12px;
  padding: 30px;
  text-align: center;
  border: 2px solid #e2e8f0;
  transition: transform 0.2s;
}
.plan-card:hover { transform: translateY(-5px); }
.plan-icon { font-size: 2rem; margin-bottom: 1rem; }
.plan-desc { color: #64748b; margin-bottom: 1.5rem; }

/* --------------------------------------------------
   CTA
--------------------------------------------------- */
.cta {
  padding: 80px 0;
  text-align: center;
  background: linear-gradient(135deg, #ff6f61 0%, #e55a5a 100%);
}
.cta h2 { color: #fff; }
.cta-buttons {
  display: flex;
  justify-content: center;
  gap: 1rem;
}
.cta-buttons a {
  text-decoration: none;
  color: #fff;
  font-weight: 700;
  transition: opacity 0.3s;
}
.cta-buttons a:hover { opacity: 0.9; }

/* --------------------------------------------------
   FOOTER
--------------------------------------------------- */
.footer {
  background: #1e1e2f;
  color: #a3a3c8;
  padding: 30px 0;
  text-align: center;
}
.footer p { margin: 0; font-size: 0.9rem; }

/* --------------------------------------------------
   ANIMATIONS (simple)
--------------------------------------------------- */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(30px); }
  to { opacity: 1; transform: translateY(0); }
}
.hero, .features, .pricing, .cta {
  animation: fadeUp 1s ease forwards;
}
.hero { delay: 0.1s; }
.features { delay: 0.2s; }
.pricing { delay: 0.3s; }
.cta { delay: 0.4s; }

/* --------------------------------------------------
   RESPONSIVE
--------------------------------------------------- */
@media (max-width: 768px) {
  .nav-links { display: none; }
  .hero h1 { font-size: 2.5rem; }
  .cta-buttons { flex-direction: column; }
}
