document.addEventListener('DOMContentLoaded', function () {
  // Animação simples ao clicar nos botões da CTA
  const btnGroup = document.querySelector('.btn-group');
  if (btnGroup) {
    btnGroup.addEventListener('click', function (e) {
      // Opcional: fechar a janela se for um link externo
      if (e.target.tagName === 'A') {
        e.preventDefault();
        console.log('Botão de assinatura clicado!');
      }
    });
  }

  // Botão de preços: quando clicado, mostra uma caixa de diálogo (simulada)
  document.querySelectorAll('.plan-card button').forEach(function (btn) {
    btn.addEventListener('click', function () {
      // Simulação de chamada à API de informações
      alert(`Detalhes da plan: ${btn.closest('.plan-card').querySelector('.plan-icon').textContent}`);
    });
  });

  // Animação de entrada ao rolar para baixo na seção de CTA
  const observerOptions = {
    root: null,
    threshold: 0.1,
    baseline: 0
  };
  const observer = new MutationObserver(() => {
    // Aqui você poderia adicionar lógica de scroll, mas não é necessário para o básico.
  });
  observer.observe(document.body, observerOptions);
});
